<?php require 'config.php';require 'includes/functions.php';require_admin();verify_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'';if($action==='save'){$id=(int)($_POST['id']??0);$data=[trim($_POST['name']), (int)$_POST['category_id'],trim($_POST['subcategory']),(float)$_POST['price'],(int)$_POST['stock'],trim($_POST['description']),trim($_POST['image_url']),trim($_POST['size_guide'])];if($id){$s=$pdo->prepare("UPDATE products SET name=?,category_id=?,subcategory=?,price=?,stock=?,description=?,image_url=?,size_guide=? WHERE id=?");$s->execute([...$data,$id]);}else{$s=$pdo->prepare("INSERT INTO products(name,category_id,subcategory,price,stock,description,image_url,size_guide) VALUES(?,?,?,?,?,?,?,?)");$s->execute($data);}flash('Product saved.');}elseif($action==='delete'){$pdo->prepare("UPDATE products SET active=0 WHERE id=?")->execute([(int)$_POST['id']]);flash('Product removed from the catalogue.');}go('admin.php');}
$cats=$pdo->query("SELECT * FROM categories ORDER BY sort_order,name")->fetchAll();$products=$pdo->query("SELECT p.*,c.name category_name FROM products p JOIN categories c ON c.id=p.category_id WHERE p.active=1 ORDER BY p.id DESC")->fetchAll();$orders=$pdo->query("SELECT o.*,u.name customer,u.email FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.created_at DESC LIMIT 50")->fetchAll();$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT * FROM products WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}$title='StyleHub Admin';require 'includes/header.php';?><div class="page-head"><span class="eyebrow">STORE CONTROL</span><h1>Admin dashboard</h1><p>Manage catalogue, prices, descriptions and customer orders.</p></div><section class="panel"><h2><?=$edit?'Edit product':'Add a product'?></h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=$edit['id']??0?>"><div class="admin-form"><label>Product name<input name="name" value="<?=e($edit['name']??'')?>" required></label><label>Category<select name="category_id" required><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=isset($edit['category_id'])&&$edit['category_id']==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Subcategory<input name="subcategory" value="<?=e($edit['subcategory']??'')?>" required></label><label>Price (₹)<input type="number" step=".01" min="0" name="price" value="<?=e((string)($edit['price']??''))?>" required></label><label>Stock<input type="number" min="0" name="stock" value="<?=e((string)($edit['stock']??0))?>" required></label><label>Image URL<input name="image_url" value="<?=e($edit['image_url']??'')?>" placeholder="https://..." required></label><label>Size guide<input name="size_guide" value="<?=e($edit['size_guide']??'')?>" placeholder="S, M, L, XL"></label></div><label>Description<textarea name="description" required><?=e($edit['description']??'')?></textarea></label><button class="button dark">Save product</button><?php if($edit):?> <a href="admin.php">Cancel edit</a><?php endif;?></form></section><section class="panel"><h2>Product catalogue</h2><div class="table-scroll"><table><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Actions</th></tr><?php foreach($products as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['category_name'])?> / <?=e($p['subcategory'])?></td><td><?=money($p['price'])?></td><td><?=$p['stock']?></td><td><a href="admin.php?edit=<?=$p['id']?>">Edit</a> <form class="inline" method="post"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="link danger" data-confirm="Remove this product?">Remove</button></form></td></tr><?php endforeach;?></table></div></section><section class="panel"><h2>Customer checkout / orders</h2><div class="table-scroll"><table><tr><th>Customer</th><th>Email</th><th>Order</th><th>Total</th><th>Status</th><th>Placed</th></tr><?php foreach($orders as $o):?><tr><td><?=e($o['customer'])?></td><td><?=e($o['email'])?></td><td>#SH<?=$o['id']?></td><td><?=money($o['total_amount'])?></td><td><?=e($o['status'])?></td><td><?=e($o['created_at'])?></td></tr><?php endforeach;?></table></div></section><?php require 'includes/footer.php';?>